style.css:
@-moz-document domain("roblox.com") {
body {
    background: linear-gradient(180deg, #dff3ff 0%, #b8e0ff 35%, #6eb7ff 80%, #0b234a 100%) !important;
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
    color: #0a1526 !important;
    font-family: "Inter", "Segoe UI", "Helvetica Neue", sans-serif !important;
  }

  body::before {
    content: "";
    position: fixed;
    top: 0; left: 0;
    width: 100vw; height: 100vh;
    z-index: -1;
    background:
      radial-gradient(circle at 50% 60%, rgba(255,255,255,0.45), transparent 50%),
      radial-gradient(circle at 30% 20%, rgba(255,255,255,0.4), transparent 60%),
      radial-gradient(circle at 70% 80%, rgba(255,255,255,0.25), transparent 70%);
    filter: blur(60px);
    opacity: 0.8;
    animation: glossyfloat 16s ease-in-out infinite alternate;
  }

  @keyframes glossyfloat {
    0% { transform: translateY(0) scale(1); }
    100% { transform: translateY(12px) scale(1.02); }
  }

  /* Glassy containers */
  .container, .content, .section, .game-card, .profile, .home-container {
    background: rgba(255, 255, 255, 0.3) !important;
    backdrop-filter: blur(20px) saturate(160%) brightness(1.1) !important;
    border-radius: 14px !important;
    border: 1px solid rgba(255, 255, 255, 0.35) !important;
    box-shadow: 0 12px 35px rgba(0,0,0,0.2) inset !important;
    color: #0e1b2f !important;
  }

  /* Headings and text — ensure readable on bright glass */
  h1, h2, h3, h4, h5, h6, p, span, a, label, div {
    color: #0e1b2f !important;
    text-shadow: 0 1px 2px rgba(255,255,255,0.6) !important;
  }

  a:hover {
    color: #004c99 !important;
    text-decoration: underline !important;
  }

  /* Code and input boxes */
  pre, code, textarea, input {
    background: rgba(255,255,255,0.45) !important;
    border: 1px solid rgba(255,255,255,0.4) !important;
    border-radius: 10px !important;
    color: #0e1b2f !important;
    font-family: "Fira Code", monospace !important;
    box-shadow: inset 0 1px 4px rgba(255,255,255,0.4);
  }

  /* Buttons — soft blue theme (no red) */
  button, .btn-primary, .btn-common {
    background: linear-gradient(180deg, #b8e0ff, #6eb7ff) !important;
    border: 1px solid rgba(255,255,255,0.5) !important;
    border-radius: 8px !important;
    color: #0e1b2f !important;
    font-weight: 600 !important;
    text-shadow: 0 1px 1px rgba(255,255,255,0.5) !important;
    transition: all 0.3s ease !important;
  }

  button:hover, .btn-primary:hover, .btn-common:hover {
    background: linear-gradient(180deg, #d0edff, #7ac5ff) !important;
    box-shadow: 0 0 15px rgba(110,183,255,0.4) !important;
  }

  /* Optional: glowing hover for links and inputs */
  input:focus, textarea:focus, a:hover {
    outline: none !important;
    box-shadow: 0 0 10px rgba(110,183,255,0.5) !important;
  }
}
